add_action( 'wp_footer', 'perfectpixel_copy_button_code_blocks' );

function perfectpixel_copy_button_code_blocks() {
	if ( ! is_singular() || false === stripos( (string) get_post_field( 'post_content', get_queried_object_id() ), '<pre' ) ) {
		return;
	}
	?>
	<style>
	.perfectpixel-copy-wrap{position:relative}
	.perfectpixel-copy-btn{position:absolute;top:6px;right:6px;z-index:2;padding:2px 8px;border:1px solid rgba(0,0,0,.2);border-radius:3px;background:#fff;color:#1d2327;font-size:12px;line-height:1.6;cursor:pointer;opacity:.85}
	.perfectpixel-copy-btn:hover,.perfectpixel-copy-btn:focus{opacity:1}
	</style>
	<script>
	( function ( labels ) {
		var copyText = function ( text ) {
			if ( navigator.clipboard && window.isSecureContext ) {
				return navigator.clipboard.writeText( text );
			}
			return new Promise( function ( resolve, reject ) {
				var area = document.createElement( 'textarea' );
				area.value = text;
				area.setAttribute( 'readonly', '' );
				area.style.position = 'fixed';
				area.style.opacity = '0';
				document.body.appendChild( area );
				area.select();
				var ok = document.execCommand( 'copy' );
				document.body.removeChild( area );
				return ok ? resolve() : reject();
			} );
		};
		document.querySelectorAll( '.entry-content pre, .wp-block-post-content pre, article pre' ).forEach( function ( pre ) {
			if ( pre.parentNode.classList.contains( 'perfectpixel-copy-wrap' ) ) {
				return;
			}
			var wrap = document.createElement( 'div' );
			wrap.className = 'perfectpixel-copy-wrap';
			pre.parentNode.insertBefore( wrap, pre );
			wrap.appendChild( pre );
			var btn = document.createElement( 'button' );
			btn.type = 'button';
			btn.className = 'perfectpixel-copy-btn';
			btn.textContent = labels.copy;
			btn.addEventListener( 'click', function () {
				var source = pre.querySelector( 'code' ) || pre;
				copyText( source.innerText ).then( function () {
					btn.textContent = labels.done;
					setTimeout( function () {
						btn.textContent = labels.copy;
					}, 2000 );
				} );
			} );
			wrap.appendChild( btn );
		} );
	} )( <?php echo wp_json_encode( array( 'copy' => '{{copy_code_button_text}}', 'done' => '{{copy_code_done_text}}' ) ); ?> );
	</script>
	<?php
}
